  if(action==='audio'){const index=Number(el.dataset.index);const process=el.dataset.process||phase;const item=content[process]?.[index];if(item)speak(item.en||item.audio||item.example);update();return {}}
  if(action==='audio-question'){const index=Number(el.dataset.index),process=el.dataset.process;const questions=content[process]?.filter(x=>QUESTION_TYPES.includes(x.type));const item=questions?.[index];if(phase!==process||item?.type!=='audioChoice')return {};const key=process+':'+item.id;if(ui.playingQuestion===key){ui.playingQuestion=null;playbackToken++;window.speechSynthesis?.cancel?.();update();return {}}ui.playingQuestion=key;const boxId=progress.boxId,token=++playbackToken;const started=speak(item.audio,()=>{if(token===playbackToken&&ui.playingQuestion===key&&progress.boxId===boxId){ui.playingQuestion=null;update()}});if(!started)ui.playingQuestion=null;update();return {}}
  if(action==='mic'){mic(Number(el.dataset.index),update);return {}}
  if(action==='prev'){progress.card=Math.max(0,progress.card-1);progress.flipped=false;persist();update();return {}}
  if(action==='next'){
   if(phase==='vocab'){
    if(content.vocab[progress.card]?.type==='word'&&!progress.flipped&&!progress.reviewed.includes(progress.card)){progress.feedback='اقلب البطاقة واقرأ معناها قبل المتابعة.';update();return {}}
    if(!progress.reviewed.includes(progress.card))progress.reviewed.push(progress.card);
   }
   if(phase==='listen'&&(ui.micBusy||ui.recording||progress.spoken[progress.card]?.method!=='recorded')){progress.feedback='سجّل صوتك وأوقف التسجيل قبل المتابعة.';update();return {}}
   if(progress.card>=content[phase].length-1){if(!canAdvance(content)){progress.feedback='أكمل عناصر هذا الجزء أولاً.';update();return {}}ui.playingQuestion=null;playbackToken++;window.speechSynthesis?.cancel?.();recordings.clear();progress.phase++;progress.card=0}
   else progress.card++;
   progress.flipped=false;persist();update();return {}
  }
  if(action==='menu-add'){ui.screen='add-select';ui.notice='';update();return {}}
  if(action==='menu-edit'){ui.screen='edit-select';ui.notice='';update();return {}}
  if(action==='menu-clear'){Object.assign(ui,{screen:'clear-menu',notice:'',clearScope:null,clearLanguage:null,clearLevel:null,clearStep:null,clearBox:null});update();return {}}
  if(action==='clear-scope'){const scope=el.dataset.value;if(!['language','level','step','box'].includes(scope))return {};Object.assign(ui,{clearScope:scope,clearLanguage:null,clearLevel:null,clearStep:null,clearBox:null,notice:''});ui.screen=scope==='language'?'clear-language':'clear-level';update();return {}}
  if(action==='clear-pick-language'){if(el.dataset.value!==CONTENT_GEOMETRY.language.code)return {};ui.clearLanguage=el.dataset.value;ui.screen='clear-confirm';ui.notice='';update();return {}}
  if(action==='clear-pick-level'){const value=Number(el.dataset.value);if(!Number.isInteger(value)||value<1||value>CONTENT_GEOMETRY.levels)return {};ui.clearLevel=value;ui.clearStep=null;ui.clearBox=null;ui.screen=ui.clearScope==='level'?'clear-confirm':'clear-step';ui.notice='';update();return {}}
  if(action==='clear-pick-step'){const value=Number(el.dataset.value);if(!Number.isInteger(value)||value<1||value>CONTENT_GEOMETRY.steps)return {};ui.clearStep=value;ui.clearBox=null;ui.screen=ui.clearScope==='step'?'clear-confirm':'clear-box';ui.notice='';update();return {}}
  if(action==='clear-pick-box'){const value=Number(el.dataset.value);if(!Number.isInteger(value)||value<1||value>CONTENT_GEOMETRY.boxes)return {};ui.clearBox=value;ui.screen='clear-confirm';ui.notice='';update();return {}}
  if(action==='clear-back'){if(ui.screen==='clear-language'||ui.screen==='clear-level')ui.screen='clear-menu';else if(ui.screen==='clear-step')ui.screen='clear-level';else if(ui.screen==='clear-box')ui.screen='clear-step';else if(ui.screen==='clear-confirm')ui.screen=ui.clearScope==='language'?'clear-language':ui.clearScope==='level'?'clear-level':ui.clearScope==='step'?'clear-step':'clear-box';else ui.screen='clear-menu';ui.notice='';update();return {}}
  if(action==='confirm-clear-content'){const result=clearContentSelection();if(result.stored){ui.notice='تم مسح '+result.label+' ('+result.count+' صندوقاً).';ui.screen='clear-done'}else ui.notice=result.count?'تعذّر حفظ عملية المسح. لم يتغير المحتوى؛ حاول مرة أخرى.':'اختر نطاقاً صالحاً للمسح.';update();return {}}
  if(action==='view-imported'){if(importing.firstBox){ui.previewBox=importing.firstBox;ui.sheet=false;update()}return {}}
  if(action==='preview-box'){const id=Number(el.dataset.value);if(Number.isInteger(id)&&id>=1&&id<=1000){ui.previewBox=id;ui.sheet=false;update()}return {}}
