 function questionAudio(item,index,process){const playing=ui.playingQuestion===process+':'+item.id;return `<div class="zone-question-audio"><div class="zone-question-audio-top"><span class="zone-question-audio-tag">مقطع صوتي · English</span><span class="zone-question-audio-hint">استمع ثم اختر المعنى</span></div><button type="button" class="zone-question-play ${playing?'is-playing':''}" data-zone="audio-question" data-process="${process}" data-index="${index}" aria-label="${playing?'إيقاف':'تشغيل'} صوت السؤال ${index+1}" aria-pressed="${playing}"><span class="zone-question-speaker">${speakerIcon}</span><span class="zone-question-play-copy"><strong>${playing?'إيقاف الاستماع':'استمع إلى السؤال'}</strong><small>${playing?'الصوت قيد التشغيل':'اضغط للتشغيل، واستمع مجدداً متى شئت'}</small></span><span class="zone-question-wave" aria-hidden="true"><i></i><i></i><i></i><i></i><i></i></span></button></div>`}
 function imageView(item){return `<figure class="zone-image-frame"><img src="${safe(item.image)}" alt="صورة تعليمية" loading="lazy" referrerpolicy="no-referrer"><figcaption>انظر إلى الصورة</figcaption></figure>`}
 function vocabImageWord(item){return `<article class="zone-image-word-card"><div class="zone-image-word-media"><span class="zone-image-word-badge">IMAGE WORD</span><img src="${safe(item.image)}" alt="${safe(item.en)}" loading="eager" decoding="async" referrerpolicy="no-referrer"></div><div class="zone-image-word-copy"><span class="zone-image-word-kicker">ENGLISH · LOOK + LISTEN</span><strong class="zone-image-word-text" lang="en" dir="ltr">${safe(item.en)}</strong><span class="zone-image-word-arabic" lang="ar" dir="rtl">${safe(item.ar)}</span>${btn('replay-word',speakerIcon+'<span>استمع مجدداً</span>',`class="zone-image-word-audio" aria-label="استمع إلى ${safe(item.en)} مجدداً"`)}</div></article>`}
