 function render({snapshot}){if(ui.previewBox)return preview({snapshot});const content=getContent(progress.boxId),phase=PHASES[progress.phase];const body=phase.key==='vocab'?vocabulary(content):phase.key==='listen'?listening(content):phase.key==='grammar'?grammar(content):quiz(content,phase.key,phase.key==='exam'?'أثبت ما تعلّمته.':phase.key==='checkpointVocab'?'هل استقرّت الكلمات؟':'هل سمعت المعنى؟',phase.key==='exam'?'أسئلة مفردات وقواعد وكتابة؛ تحتاج ٧٥٪ وإجابة الكتابة الصحيحة.':'اختبار قصير قبل الجزء التالي؛ تحتاج ٧٠٪.');return `<div class="zone zone-${phase.key}"><header class="zone-header">${btn('exit','الخروج من الصندوق','class="zone-exit"')}<div class="zone-brand" lang="ar" dir="rtl"><span class="logo-word">لُبلُب</span></div><span class="zone-save">تقدّمك يُحفظ تلقائياً</span></header><main class="zone-main"><nav class="zone-track" aria-label="مراحل الصندوق">${PHASES.map((p,i)=>`<span class="${i===progress.phase?'current':i<progress.phase?'done':''}" ${i===progress.phase?'aria-current="step"':''}><i>${String(i+1).padStart(2,'0')}</i>${p.name}</span>`).join('')}</nav>${body}${progress.feedback?`<p class="zone-feedback" role="status">${safe(progress.feedback)}</p>`:''}</main>${btn('control','إدارة المحتوى','class="zone-control" aria-label="إدارة المحتوى التعليمي"')}${editor()}</div>`}
